from pathlib import Path

root = Path(__file__).resolve().parent
source = root / "libc.s"
output = root.parent / "src" / "resources" / "embedded_libc.cpp"
header = root.parent / "src" / "resources" / "embedded_libc.hpp"
data = source.read_bytes()

header.write_text(
    """#pragma once

#include <cstdint>
#include <span>

namespace kr16 {

std::span<const std::uint8_t> embedded_libc_source();

}  // namespace kr16
""",
    encoding="utf-8",
)

lines = [
    "// Generated by resources/embed_libc.py; do not edit by hand.",
    '#include "resources/embedded_libc.hpp"',
    "",
    "#include <array>",
    "",
    "namespace kr16 {",
    "namespace {",
    "constexpr std::array<std::uint8_t, " + str(len(data)) + "> kLibc = {",
]
for i in range(0, len(data), 16):
    chunk = data[i : i + 16]
    lines.append("    " + ", ".join(f"0x{b:02X}" for b in chunk) + ",")
lines.extend(
    [
        "};",
        "}  // namespace",
        "",
        "std::span<const std::uint8_t> embedded_libc_source() {",
        "    return kLibc;",
        "}",
        "",
        "}  // namespace kr16",
    ]
)
output.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(output)
